function describeHost() {
  if (typeof window !== "undefined" && typeof document !== "undefined") {
    return "browser";
  }
  return "node";
}

console.log(describeHost());
// browser → "browser"
// node    → "node"

Automatic Semicolon Insertion adds a semicolon right after `return` because the next token is on a new line, so the function returns `undefined` and `42;` becomes an unreachable expression. Fix it by keeping the value on the same line:

function getTotal() {
  return 42;
}

console.log(getTotal()); // 42

